import React, { useState, useEffect } from 'react';
import { FaCalendarAlt, FaSearch, FaChalkboard } from 'react-icons/fa';

const Clases = () => {
  const [clases, setClases] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');

  // Datos de ejemplo (aqui se llama la api)
  useEffect(() => {
    const mockClases = [
      { id: 1, materia: 'Matemáticas', grado: '10A', horario: 'Lunes 8:00-10:00', aula: 'A201' },
      { id: 2, materia: 'Física', grado: '11B', horario: 'Martes 10:00-12:00', aula: 'B305' },
      { id: 3, materia: 'Química', grado: '9C', horario: 'Miércoles 14:00-16:00', aula: 'Lab1' },
    ];
    setClases(mockClases);
  }, []);

  const filteredClases = clases.filter(clase =>
    clase.materia.toLowerCase().includes(searchTerm.toLowerCase()) ||
    clase.grado.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="docente-content">
      <h2><FaChalkboard /> Mis Clases</h2>
      
      <div className="search-bar">
        <FaSearch />
        <input
          type="text"
          placeholder="Buscar clase por materia o grado..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="table-container">
        <table>
          <thead>
            <tr>
              <th>Materia</th>
              <th>Grado</th>
              <th>Horario</th>
              <th>Aula</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {filteredClases.map((clase) => (
              <tr key={clase.id}>
                <td>{clase.materia}</td>
                <td>{clase.grado}</td>
                <td><FaCalendarAlt /> {clase.horario}</td>
                <td>{clase.aula}</td>
                <td>
                  <button className="btn-view">Ver Detalles</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Clases;
